  'publishTarget.hint.local': { 'zh-CN': '公司服务器可按部门或用途建发布区，所有内容类型均可自由组合。', 'ja-JP': '社内サーバーでは部署や用途ごとに公開先を作成し、すべてのタイプを自由に組み合わせられます。', 'en-US': 'Company servers can use publish areas by department or purpose with any content type combination.' },
  'publishTarget.hint.sftp': { 'zh-CN': '远程公司服务器支持所有内容类型自由组合。', 'ja-JP': 'リモート社内サーバーではすべてのコンテンツタイプを自由に組み合わせられます。', 'en-US': 'Remote company servers support any content type combination.' },
  'publishTarget.hint.github': { 'zh-CN': 'GitHub Repository 将原始文件直接上传到仓库目录，不创建内容文件夹或 index.html；超过 100 MiB 的单文件使用 Git LFS。', 'ja-JP': 'GitHub Repository は元ファイルをリポジトリ内ディレクトリへ直接アップロードし、コンテンツフォルダや index.html は作成しません。100 MiB を超える単一ファイルは Git LFS を使用します。', 'en-US': 'GitHub Repository uploads source files directly to the repository path without creating a content folder or index.html. Files over 100 MiB use Git LFS.' },
  'publishTarget.hint.githubPages': { 'zh-CN': 'GitHub Pages 是静态站点，仅排除依赖后端运行的动态页面，且不支持 Git LFS。', 'ja-JP': 'GitHub Pages は静的サイトです。バックエンドが必要な動的ページは対象外で、Git LFS にも対応しません。', 'en-US': 'GitHub Pages is static hosting. Dynamic pages are excluded, and Git LFS is not supported.' },
  'publishTarget.hint.onedrive': { 'zh-CN': 'OneDrive 支持所有文件类型；大文件由上传会话分块传输。', 'ja-JP': 'OneDrive はすべてのファイルタイプに対応し、大容量ファイルはアップロードセッションで分割転送します。', 'en-US': 'OneDrive supports all file types and uploads large files in chunks.' },
  'publishTarget.hint.dropbox': { 'zh-CN': 'Dropbox 支持所有文件类型；超过 150 MiB 使用上传会话分块传输。', 'ja-JP': 'Dropbox はすべてのファイルタイプに対応し、150 MiB を超えるファイルは分割転送します。', 'en-US': 'Dropbox supports all file types and uses chunked uploads above 150 MiB.' },
  'publishTarget.hint.instagram': { 'zh-CN': 'Instagram Reels 每条内容只允许一个 MP4 或 MOV 视频；Meta 会从配置的公网 HTTPS 地址拉取视频。', 'ja-JP': 'Instagram Reels は1件につき MP4 または MOV 動画1つのみ対応し、Meta が設定済みの公開 HTTPS URL から取得します。', 'en-US': 'Instagram Reels accepts one MP4 or MOV video per item. Meta fetches it from the configured public HTTPS URL.' },
